 static void sourceProducer(){
  for(int attack:new int[]{0,1,2,3,4,5,99})for(int paralysis:new int[]{0,5})for(int roll=0;roll<100;roll++){
   var oracle=new NpcSourceModeOracle(roll,0,false,false,10,0,attack,paralysis);var receiver=new NpcSourceModeOracle.Target();oracle.poison(receiver);var kind=ClassicWorldMonsterPoisonAttack.resolve(attack,roll+1);List<String> expected=switch(kind){case NONE->List.of();case DAMAGE->List.of("DAMAGE:3000:5");case SILENCE->List.of("SILENCE");case PARALYSIS->List.of("PARALYSIS:20000:45000");};check(receiver.events.equals(expected),"actual compiled source poison factory/roll/timing kind="+attack+" roll="+(roll+1));check(oracle.randomCalls==(attack==1||attack==2||attack==4?1:0),"source supported poison kinds draw once; unsupported kinds draw zero times");
  }
 }
 static ClassicWorldMonsterPoisonAttack.Kind poisonKind(ClientSession pc)throws Exception{return (ClassicWorldMonsterPoisonAttack.Kind)get(pc,"classicWorldPoisonKind");}
