 static void noDamage(ClientSession pc)throws Exception{patience(pc,pc.playerObjectId());((BattleDragonSkinStatus)get(pc,"dragonSkinStatus")).activate(System.nanoTime(),600,10);((BattleAbilityStatus)get(pc,"abilityStatus")).activateReductionArmor(System.nanoTime(),600);for(int item=40000;item<60000;item++){var recipe=BattleCookingCatalog.find(item);if(recipe!=null&&recipe.damageReduction()==5){((BattleCookingStatus)get(pc,"cookingStatus")).activate(System.nanoTime(),recipe,600);return;}}throw new AssertionError("no native cooking fixture for deterministic zero damage");}
